#!/usr/bin/env bash
set -uo pipefail

# ── setup-browser.sh ─────────────────────────────────────────────────
# Checks prerequisites for agent-browser and installs Chromium if needed.
# Run this BEFORE any agent-browser commands.
#
# Exit codes:
#   0 = ready to use agent-browser
#   1 = npx/Node.js not available (cannot proceed)
#   2 = agent-browser install failed (Chromium download issue)
#
# Output (structured for agent parsing):
#   BROWSER_SETUP_STATUS:READY           — all good, agent-browser is usable
#   BROWSER_SETUP_STATUS:MISSING_NODE    — Node.js/npx not found
#   BROWSER_SETUP_STATUS:INSTALL_FAILED  — Chromium install failed
#   BROWSER_SETUP_STATUS:SKIPPED         — user opted out or non-critical failure
# ─────────────────────────────────────────────────────────────────────

# ── 1. Check Node.js / npx ──────────────────────────────────────────
if ! command -v npx &>/dev/null; then
  echo "BROWSER_SETUP_STATUS:MISSING_NODE"
  echo "Error: npx is not installed. agent-browser requires Node.js (v18+)."
  echo ""
  echo "Install Node.js from: https://nodejs.org/"
  echo "  macOS:   brew install node"
  echo "  Linux:   curl -fsSL https://deb.nodesource.com/setup_lts.x | sudo -E bash - && sudo apt-get install -y nodejs"
  echo "  Windows: Download from https://nodejs.org/"
  exit 1
fi

NODE_VERSION=$(node -v 2>/dev/null | sed 's/v//' | cut -d. -f1)
echo "Found Node.js $(node -v 2>/dev/null) with npx $(npx --version 2>/dev/null)"

if [[ -n "$NODE_VERSION" ]] && [[ "$NODE_VERSION" -lt 18 ]]; then
  echo "Warning: Node.js v18+ is recommended. Current version: $(node -v 2>/dev/null)"
fi

# ── 2. Check if agent-browser is accessible ─────────────────────────
echo "Checking agent-browser availability..."
if npx agent-browser --version &>/dev/null; then
  AB_VERSION=$(npx agent-browser --version 2>/dev/null)
  echo "Found agent-browser $AB_VERSION"
else
  echo "agent-browser not found locally. npx will download it on first use."
fi

# ── 3. Check for system Chrome/Chromium (fallback browser) ───────────
# Playwright (used by agent-browser) falls back to system Chrome/Chromium
# if its managed browser isn't installed. Detect this so we know whether
# agent-browser install is strictly required.
OS_TYPE="$(uname -s)"
HAS_SYSTEM_BROWSER=false
if [[ "$OS_TYPE" == "Darwin" ]]; then
  # macOS: check common Chrome/Chromium locations
  if [[ -d "/Applications/Google Chrome.app" ]] || [[ -d "/Applications/Chromium.app" ]]; then
    HAS_SYSTEM_BROWSER=true
  fi
elif [[ "$OS_TYPE" == MINGW* ]] || [[ "$OS_TYPE" == MSYS* ]] || [[ "$OS_TYPE" == CYGWIN* ]] || [[ "$OS_TYPE" == *_NT* ]]; then
  # Windows (Git Bash / MSYS2 / Cygwin / WSL interop)
  WIN_CHROME_PATHS=(
    "/c/Program Files/Google/Chrome/Application/chrome.exe"
    "/c/Program Files (x86)/Google/Chrome/Application/chrome.exe"
    "$LOCALAPPDATA/Google/Chrome/Application/chrome.exe"
    "$PROGRAMFILES/Google/Chrome/Application/chrome.exe"
  )
  for p in "${WIN_CHROME_PATHS[@]}"; do
    if [[ -f "$p" ]] 2>/dev/null; then
      HAS_SYSTEM_BROWSER=true
      break
    fi
  done
elif [[ "$OS_TYPE" == "Linux" ]]; then
  # Linux: check for chrome/chromium in PATH
  if command -v google-chrome &>/dev/null || command -v chromium-browser &>/dev/null || command -v chromium &>/dev/null; then
    HAS_SYSTEM_BROWSER=true
  fi
fi

if $HAS_SYSTEM_BROWSER; then
  echo "Found system Chrome/Chromium (will be used as fallback)."
fi

# ── 4. Install Chromium if needed ────────────────────────────────────
# agent-browser install downloads Chromium via Playwright.
# It's safe to re-run — it skips if already installed.
echo "Ensuring Playwright-managed Chromium is installed..."
if npx agent-browser install 2>&1; then
  echo "Chromium is ready."
else
  INSTALL_EXIT=$?
  echo ""
  echo "Warning: agent-browser install exited with code $INSTALL_EXIT."
  echo "This may mean the Playwright-managed Chromium could not be downloaded."
  echo ""

  # Check if it's a Linux system deps issue
  if [[ "$(uname -s)" == "Linux" ]]; then
    echo "On Linux, you may need system dependencies:"
    echo "  npx agent-browser install --with-deps"
    echo "  # or: npx playwright install-deps chromium"
    echo ""
  fi

  # If system Chrome exists, agent-browser can still work via fallback
  if $HAS_SYSTEM_BROWSER; then
    echo "System Chrome/Chromium detected — agent-browser should still work via fallback."
    echo ""
    echo "BROWSER_SETUP_STATUS:READY"
    echo "agent-browser is ready (using system browser as fallback)."
    exit 0
  fi

  echo "BROWSER_SETUP_STATUS:INSTALL_FAILED"
  echo "No Playwright-managed Chromium and no system Chrome/Chromium found."
  echo "agent-browser will not work. Browser commands will fail."
  echo "You can try manually: npx agent-browser install"
  exit 2
fi

# ── 5. All good ──────────────────────────────────────────────────────
echo ""
echo "BROWSER_SETUP_STATUS:READY"
echo "agent-browser is ready. You can now run browser commands."
